import{_ as t,c as a,o as r,ag as i}from"./chunks/framework.ARG558ZT.js";const h=JSON.parse('{"title":"Homework source notes, corrections and provenance","description":"","frontmatter":{},"headers":[],"relativePath":"practice/aws/source-notes.md","filePath":"practice/aws/source-notes.md"}'),o={name:"practice/aws/source-notes.md"};function s(n,e,c,d,l,p){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="homework-source-notes-corrections-and-provenance" tabindex="-1">Homework source notes, corrections and provenance <a class="header-anchor" href="#homework-source-notes-corrections-and-provenance" aria-label="Permalink to “Homework source notes, corrections and provenance”">​</a></h1><p>The task status in this repository is deliberate: <strong>all supplied optional and bonus work is required locally</strong>. Original course grading may still omit it. No task specification authorizes this assistant to create accounts, deploy cloud resources, send notifications, push or perform other live lab actions.</p><h2 id="technical-corrections-before-implementation" tabindex="-1">Technical corrections before implementation <a class="header-anchor" href="#technical-corrections-before-implementation" aria-label="Permalink to “Technical corrections before implementation”">​</a></h2><table tabindex="0"><thead><tr><th>Source issue</th><th>Interpretation in this learning path</th></tr></thead><tbody><tr><td>CloudFront task combines static website endpoint with OAC/OAI</td><td>Use a bucket REST origin for private OAC/OAI delivery. A website endpoint is a custom origin and cannot use OAC/OAI. Preserve website hosting as a separate comparison.</td></tr><tr><td>Alias <code>latest</code> is told to point to <code>$LATEST</code></td><td>Publish a numbered version and move the alias to that version. Alias name and unpublished <code>$LATEST</code> are different concepts.</td></tr><tr><td>Normal successful orders expected in DLQ</td><td>Induce a controlled processing failure; demonstrate successful and failed paths separately.</td></tr><tr><td>Public subnet alone described as granting public reachability</td><td>Check actual public accessibility/addressing, route and security configuration. Public-subnet Lambda placement does not give the function a public IP.</td></tr><tr><td>A public DB and “Lambdas only” ingress plus local migration</td><td>Temporarily permit only the learner&#39;s IP for migration as specified, then remove that ingress before final evaluation. Do not make the DB generally open.</td></tr><tr><td>“Micro” or fixed service prices imply free use</td><td>Verify account/Region/service eligibility and current pricing. No lab promises zero charges. Budgets notify; they are not universal spending caps.</td></tr><tr><td>CloudFormation sample opens SSH to everyone</td><td>Restrict administrative SSH to the learner&#39;s IP and document the deviation from the broad historical example. Keep public web access distinct.</td></tr><tr><td>IAM long-lived administrator keys</td><td>Preserve the source exercise with synthetic learning scope; understand temporary credentials as the preferred broader pattern. Never create root access keys or publish keys.</td></tr><tr><td>S3 public object demonstration assumes ACLs</td><td>Check Object Ownership/Block Public Access and use supported explicit policy settings. Restore private access after the disposable demonstration.</td></tr><tr><td>Module 7 dependency explanation reverses the reference</td><td>Import depends on Authorization because it receives its Lambda. An automatically attached Lambda permission can introduce a reverse reference; the explicit invocation role is intended to avoid that cycle. Inspect the synthesized dependency graph.</td></tr><tr><td>AI text limit says 5,000 characters</td><td>Validate the Comprehend API&#39;s UTF-8 byte limit for the selected operation; characters are not interchangeable with bytes.</td></tr><tr><td>AI sample architecture includes API Gateway but deployment omits it</td><td>Add and verify the actual HTTP integration, event parsing, response contract and permissions. Direct Lambda invocation alone does not demonstrate the advertised API.</td></tr><tr><td>AI sample mixes ES imports with incomplete package configuration</td><td>Configure ESM or a build output deliberately and include required package metadata/dependencies. Choose a currently supported runtime instead of copying Node.js 18 unchanged.</td></tr><tr><td>Two labs numbered 11</td><td>A11 is CI/CD; A12 is the supplied Q/AI lab. Original names remain source context.</td></tr><tr><td>Source CLI snippets contain typographic dashes or broken arguments</td><td>Use valid ASCII command options and verify each variable&#39;s meaning; source screenshots are not executable specifications.</td></tr><tr><td>RDS lab&#39;s aggregation explanation suggests items need not transfer</td><td>The API still returns items. Compute <code>SUM</code> in SQL as required, without claiming the complete response no longer includes item rows.</td></tr></tbody></table><p>These notes clarify outcomes without silently changing exact Practitioner API fields, exported names or Autocode assertions. For a live-version conflict with a required engine/runtime, report it and preserve the original acceptance requirement; do not invent an unapproved replacement and claim it passes.</p><p>Official behavior references: <a href="https://docs.aws.amazon.com/AmazonCloudFront/latest/DeveloperGuide/private-content-restricting-access-to-s3.html" target="_blank" rel="noreferrer">CloudFront private origins</a>, <a href="https://docs.aws.amazon.com/lambda/latest/dg/configuration-aliases.html" target="_blank" rel="noreferrer">Lambda aliases</a>, <a href="https://docs.aws.amazon.com/AWSSimpleQueueService/latest/SQSDeveloperGuide/sqs-dead-letter-queues.html" target="_blank" rel="noreferrer">SQS DLQs</a>, <a href="https://docs.aws.amazon.com/comprehend/latest/APIReference/API_DetectSentiment.html" target="_blank" rel="noreferrer">Comprehend sentiment input</a>, <a href="https://docs.aws.amazon.com/IAM/latest/UserGuide/best-practices.html" target="_blank" rel="noreferrer">IAM security</a>. These key behaviors were checked during the homework assessment on 28 October 2026; service availability and exact console screens still require current verification when implementing.</p><h2 id="source-register" tabindex="-1">Source register <a class="header-anchor" href="#source-register" aria-label="Permalink to “Source register”">​</a></h2><ul><li>Practitioner P01: inline account/template assignment supplied in chat. P02–P08: seven supplied text attachments, preserved beside the readable pages as downloadable source text.</li><li>Associate A01/A02/A04/A05/A07/A08/A09/A10: inline task lists supplied in chat, organized into the required checklists without making alternatives into separate mandatory implementations.</li><li>Associate A03/A06/A11/A12: supplied text attachments retained as downloadable source text; A03 is also summarized as a structured checklist.</li><li>Supporting PDFs: IAM Practice Guide (76 pages), EC2 Practice Guide (58), S3 Practice Guide (83), CloudFront Practice Guide (45), CloudFormation Practice Guide (101), VPC Practice Guide (58), RDS/PostgreSQL-to-EC2 Guide (39), DynamoDB-to-EC2 Guide (32), SNS/SQS Practice Guide (41), Serverless Practice Guide (39), CI/CD Practice Guide (113).</li></ul><p>The PDFs supplied by the learner remain the original screenshot walkthroughs; they are not duplicated into this site. Their substantive bonuses are included here: CLI IAM lifecycle (A02), S3 role switching and version-aware deletion (A04), endpoint/flow-log work and cleanup (A07), and CLI pipeline tuning/parallelization (A11). Database deployment walkthroughs support the now-required A08 deployments. Incidental “optionally add tags” UI choices are not separate projects.</p><h2 id="evidence-boundaries" tabindex="-1">Evidence boundaries <a class="header-anchor" href="#evidence-boundaries" aria-label="Permalink to “Evidence boundaries”">​</a></h2><p>No AWS account changes, emails/SMS, deployments, submissions or homework implementations have been performed while preparing these pages. Documentation build/link checks establish that the learning site works, not that learner solutions pass Autocode. Raw source files may retain original “optional,” submission or outdated technical wording; use the interpreted module page and corrections above for this path.</p>',11)])])}const m=t(o,[["render",s]]);export{h as __pageData,m as default};
